    [TestCase("light_weapon", 9)] // TEST-SUPPORT: WEAPON-CAPACITY-035 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
    [TestCase("heavy_weapon", 3)] // TEST-SUPPORT: WEAPON-CAPACITY-036 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
    public void EndgameFixtureAcceptsExactlyNineCapacity(string category, int count) // TEST-SUPPORT: WEAPON-CAPACITY-037 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
    { // TEST-SUPPORT: WEAPON-CAPACITY-038 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        using var inventory = new InventoryController(); // TEST-SUPPORT: WEAPON-CAPACITY-039 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        using var equipment = new EquipmentController(inventory.Items); // TEST-SUPPORT: WEAPON-CAPACITY-040 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        Assert.That(Equip(inventory, equipment, Add(inventory, "mock_standard_weapon_fixture"), "weapon_fixture"), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-041 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        for (var i = 1; i <= count; i++) // TEST-SUPPORT: WEAPON-CAPACITY-042 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
            Assert.That(Equip(inventory, equipment, Add(inventory, "mock_standard_" + category), "weapon_" + i), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-043 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        Assert.That(equipment.Snapshot.UsedWeaponSlots, Is.EqualTo(9)); // TEST-SUPPORT: WEAPON-CAPACITY-044 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        Assert.That(equipment.Snapshot.FreeWeaponSlots, Is.Zero); // TEST-SUPPORT: WEAPON-CAPACITY-045 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        var extra = Add(inventory, "mock_standard_heavy_weapon"); // TEST-SUPPORT: WEAPON-CAPACITY-046 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        var before = equipment.Snapshot; // TEST-SUPPORT: WEAPON-CAPACITY-047 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        Assert.That(Equip(inventory, equipment, extra, count == 9 ? "weapon_1" : "weapon_4"), Is.EqualTo(TransferResult.IncompatiblePlacement)); // TEST-SUPPORT: WEAPON-CAPACITY-048 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
        Assert.That(equipment.Snapshot, Is.SameAs(before)); // TEST-SUPPORT: WEAPON-CAPACITY-049 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity
    } // TEST-SUPPORT: WEAPON-CAPACITY-050 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.EndgameFixtureAcceptsExactlyNineCapacity

