    [Test] // TEST-SUPPORT: WEAPON-CAPACITY-078 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
    public void RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory() // TEST-SUPPORT: WEAPON-CAPACITY-079 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
    { // TEST-SUPPORT: WEAPON-CAPACITY-080 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        using var inventory = new InventoryController(); // TEST-SUPPORT: WEAPON-CAPACITY-081 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        using var equipment = new EquipmentController(inventory.Items); // TEST-SUPPORT: WEAPON-CAPACITY-082 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var fixture = Add(inventory, "mock_standard_weapon_fixture"); // TEST-SUPPORT: WEAPON-CAPACITY-083 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(Equip(inventory, equipment, fixture, "weapon_fixture"), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-084 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var weapons = new[] { Add(inventory, "mock_standard_light_weapon"), Add(inventory, "mock_standard_medium_weapon"), Add(inventory, "mock_standard_heavy_weapon") }; // TEST-SUPPORT: WEAPON-CAPACITY-085 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        for (var i = 0; i < weapons.Length; i++) // TEST-SUPPORT: WEAPON-CAPACITY-086 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            Assert.That(Equip(inventory, equipment, weapons[i], "weapon_" + (i + 1)), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-087 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(inventory.Items.CreateItems(inventory.Container, "mock_standard_engine", 127), Is.EqualTo(InventoryResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-088 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var inventoryBefore = inventory.Snapshot; // TEST-SUPPORT: WEAPON-CAPACITY-089 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var equipmentBefore = equipment.Snapshot; // TEST-SUPPORT: WEAPON-CAPACITY-090 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var source = new ItemLocation(equipment.Container.Id, equipment.FindSlot("weapon_fixture")); // TEST-SUPPORT: WEAPON-CAPACITY-091 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var destination = new ItemLocation(inventory.Container.Id, 127); // TEST-SUPPORT: WEAPON-CAPACITY-092 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(inventory.Items.TransferItem(fixture.Id, source, destination, equipment.Revision, inventory.Revision, commit: false), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-093 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(inventory.Snapshot, Is.SameAs(inventoryBefore)); // TEST-SUPPORT: WEAPON-CAPACITY-094 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(equipment.Snapshot, Is.SameAs(equipmentBefore)); // TEST-SUPPORT: WEAPON-CAPACITY-095 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        var notifications = 0; // TEST-SUPPORT: WEAPON-CAPACITY-096 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        void Observe() // TEST-SUPPORT: WEAPON-CAPACITY-097 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        { // TEST-SUPPORT: WEAPON-CAPACITY-098 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            notifications++; // TEST-SUPPORT: WEAPON-CAPACITY-099 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            Assert.That(equipment.Snapshot.MaxWeaponSlots, Is.Zero); // TEST-SUPPORT: WEAPON-CAPACITY-100 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            Assert.That(equipment.Snapshot.UsedWeaponSlots, Is.Zero); // TEST-SUPPORT: WEAPON-CAPACITY-101 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            Assert.That(inventory.Snapshot.Occupied, Has.Count.EqualTo(131)); // TEST-SUPPORT: WEAPON-CAPACITY-102 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            Assert.That(inventory.Capacity, Is.EqualTo(192)); // TEST-SUPPORT: WEAPON-CAPACITY-103 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
            foreach (var weapon in weapons) // TEST-SUPPORT: WEAPON-CAPACITY-104 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
                Assert.That(inventory.Items.GetLocation(weapon.Id).ContainerId, Is.EqualTo(inventory.Container.Id)); // TEST-SUPPORT: WEAPON-CAPACITY-105 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        } // TEST-SUPPORT: WEAPON-CAPACITY-106 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        inventory.Changed += _ => Observe(); // TEST-SUPPORT: WEAPON-CAPACITY-107 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        equipment.Changed += _ => Observe(); // TEST-SUPPORT: WEAPON-CAPACITY-108 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
        Assert.That(inventory.Items.TransferItem(fixture.Id, source, destination, equipment.Revision, inventory.Revision), Is.EqualTo(TransferResult.Success)); // TEST-SUPPORT: WEAPON-CAPACITY-109 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.RemovingFixtureReturnsWeaponsAtomicallyAndGrowsInventory
