        var state = new ItemContainerState(equipment.Container.Id, 1, 0, slots); // TEST-SUPPORT: WEAPON-CAPACITY-150 | Tests: sMPGWM.Tests.EquipmentSystem.WeaponCapacityTests.InvalidConfirmedAndRestoredLoadoutsAreRejected
